-- ============================================================================
-- ACTUALIZACIÓN INTEGRAL REMOTA - INTERNAL MK
-- Fecha: 2026-10-15 15:49:22
-- Contenido:
--   1. Migración segura para second_partida_id en billing_requests
--   2. Tasa de cambio BCV del día (879.1225 Bs)
--   3. Actualización de Facturación #60 (Factura 1561), Req #86, Partida 350
--   4. Bitácora de operaciones de facturación
--   5. Contenedores (SUDU-8941007 = 68 cámaras, CAJU-2025 = 124 cámaras)
--   6. Inserción y/o Actualización de las 192 CÁMARAS con Costos y Precios calculados
--   7. Ajuste de AUTO_INCREMENT
-- ============================================================================

SET FOREIGN_KEY_CHECKS = 0;
START TRANSACTION;
SET NAMES utf8mb4;

-- ----------------------------------------------------------------------------
-- 1. MIGRACIÓN SEGUNDO ITEM (second_partida_id)
-- ----------------------------------------------------------------------------
SET @dbname = DATABASE();
SET @tablename = 'billing_requests';
SET @columnname = 'second_partida_id';
SET @preparedStatement = (SELECT IF(
  (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = @dbname AND TABLE_NAME = @tablename AND COLUMN_NAME = @columnname) > 0,
  'SELECT 1',
  'ALTER TABLE billing_requests ADD COLUMN second_partida_id BIGINT UNSIGNED NULL AFTER partida_id, ADD CONSTRAINT billing_requests_second_partida_id_foreign FOREIGN KEY (second_partida_id) REFERENCES inventarios(id) ON DELETE SET NULL;'
));
PREPARE alterIfNotExists FROM @preparedStatement;
EXECUTE alterIfNotExists;
DEALLOCATE PREPARE alterIfNotExists;

-- ----------------------------------------------------------------------------
-- 2. TASA BCV DEL DÍA
-- ----------------------------------------------------------------------------
ON DUPLICATE KEY UPDATE `rate` = VALUES(`rate`), `updated_at` = VALUES(`updated_at`);

-- ----------------------------------------------------------------------------
-- 3. FACTURACIÓN PARTIDA 350 / FACTURA 1561 / SOLICITUD 86
-- ----------------------------------------------------------------------------
UPDATE `inventarios` 
SET `status` = 'VENDIDO', 
    `price_sale` = '383.39', 
    `updated_at` = '2026-10-15 13:08:57' 
WHERE `id` = 350;



-- ----------------------------------------------------------------------------
-- 4. BITÁCORA DE FACTURACIÓN
-- ----------------------------------------------------------------------------

-- ----------------------------------------------------------------------------
-- 5. ACTUALIZACIÓN DE CONTENEDORES (CANTIDAD DE CÁMARAS Y METADATOS)
-- ----------------------------------------------------------------------------
ON DUPLICATE KEY UPDATE
  `camaras` = VALUES(`camaras`),
  `tasa_bcv` = VALUES(`tasa_bcv`),
  `porcentaje_utilidad` = VALUES(`porcentaje_utilidad`),
  `updated_at` = VALUES(`updated_at`);

-- ----------------------------------------------------------------------------
-- 6. DISTRIBUCIÓN DE COSTOS Y ASIGNACIÓN DE LAS 192 CÁMARAS
--    (INSERT ... ON DUPLICATE KEY UPDATE garantiza idempotencia total)
-- ----------------------------------------------------------------------------

ON DUPLICATE KEY UPDATE
    `container_id` = VALUES(`container_id`),
    `expediente` = VALUES(`expediente`),
    `costo` = VALUES(`costo`),
    `tasa_bcv` = VALUES(`tasa_bcv`),
    `fecha_tasa_bcv` = VALUES(`fecha_tasa_bcv`),
    `costo_importacion_unitario` = VALUES(`costo_importacion_unitario`),
    `prorrateo_gastos` = VALUES(`prorrateo_gastos`),
    `porcentaje_utilidad` = VALUES(`porcentaje_utilidad`),
    `price` = VALUES(`price`),
    `price_sale` = VALUES(`price_sale`),
    `status` = VALUES(`status`),
    `updated_at` = VALUES(`updated_at`);



-- ----------------------------------------------------------------------------
-- 7. AJUSTES DE AUTO_INCREMENT
-- ----------------------------------------------------------------------------
ALTER TABLE `inventarios` AUTO_INCREMENT = 819;
ALTER TABLE `billings` AUTO_INCREMENT = 61;
ALTER TABLE `billing_requests` AUTO_INCREMENT = 87;
ALTER TABLE `bitacoras` AUTO_INCREMENT = 2590;
ALTER TABLE `exchange_rates` AUTO_INCREMENT = 54;

COMMIT;
SET FOREIGN_KEY_CHECKS = 1;
